    final config = restorableBootConfig(
      connection: widget.lastConnectionStore?.connection,
      registry: widget.registry,
      sessionKeysStore: widget.sessionKeysStore,
    );
    setState(() {
      _onboardingDone = true;
      _config = config;
    });
    if (config != null) unawaited(_boot());
  }

