    this.repeatInterval = const Duration(seconds: 30),
    void Function(String message)? onBreadcrumb,
    Stopwatch? uptime,
  }) : _onBreadcrumb =
           onBreadcrumb ??
           ((message) => debugPrint('[fah] BOOT-WATCHDOG $message')),
       _uptime = uptime ?? BootSteps.uptime;

