  /// the phase is armed via [beginRestore] (and on repeat calls), so the
  /// boot path can end it in a `finally` without bookkeeping.
  void restoreDone() {
    if (!_restoreArmed) return;
    _restoreArmed = false;
    _timer?.cancel();
    _timer = null;
